// Input declarations
length = input(14, "ATR Length", 1, 100, 1)

// Model calculations — plain assignments, recomputed every bar
// ATR: Wilder RMA — validated vs TradingView
myAtra = atr(high, low, close, length)

// Signal condition as plain boolean
buySig = crossover(close, myAtra)

// Signal markers INSIDE conditionals
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}

// Unconditional rendering LAST at top level
// plot() must never be inside if-blocks; it renders every bar
plot(myAtra, "ATR", "#22cc88", 1)

// Input declarations
rangeLen = input(14, "Session Range Length")
confirmTF = input("1H", "Confirm Timeframe")

// Model calculations — plain assignments, recomputed every bar
sessHigh = highest(high, rangeLen)
sessLow = lowest(low, rangeLen)
confirmClose = security(confirmTF, close)
confirmPrevClose = security(confirmTF, close[1])

// Signal conditions as plain booleans
buySig = crossover(close, sessHigh) and confirmClose > confirmPrevClose
sellSig = crossunder(close, sessLow) and confirmClose < confirmPrevClose

// Persistent state ONLY: var with literal initial value
var position = 0.0
if buySig {
    position := 1.0
}
if sellSig {
    position := -1.0
}

// Signal markers INSIDE conditionals
if buySig {
    plotshape(bar_index, low, "Buy", "coneup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "conedown", "#ff4477")
}

// Unconditional rendering LAST at top level
plot(sessHigh, "Session High", "#22cc88", 1)
plot(sessLow, "Session Low", "#ff4477", 1)

